<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Review Camp</title><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/@tabler/core@1.4.0/dist/css/tabler.min.css"><style>body{background:#17233d;color:#fff}.wrap{max-width:720px;margin:auto;padding:30px 16px}.camp{background:linear-gradient(135deg,#78522e,#365a45);padding:25px;border-radius:20px}.cardx{background:#fff;color:#18223d;padding:25px;border-radius:18px;margin-top:18px}.answers{display:grid;gap:10px}.answers button{padding:12px;border:2px solid #ddd;border-radius:10px;background:#fff}.word{font-size:45px;font-weight:900;color:#7654bd}</style></head><body><main class="wrap"><a class="text-white" href="<?= base_url('belajar/english-quest'); ?>">← Peta Dunia</a><section class="camp mt-3"><h1>🏕️ Review Camp</h1><p>Latih kembali kosakata yang paling membutuhkan perhatian.</p></section><section class="cardx"><div class="word" id="word"></div><p id="status">Pilih arti yang benar atau gunakan latihan bicara.</p><div class="answers" id="answers"></div><button class="btn btn-outline-primary mt-3" id="speak">🎙️ Ucapkan kata</button></section></main><script>const words=<?= json_encode($words,JSON_UNESCAPED_UNICODE); ?>,url='<?= base_url('belajar/english-quest/review/submit'); ?>';let i=0;function draw(){if(i>=words.length){document.querySelector('.cardx').innerHTML='<h2>Latihan selesai! 🎉</h2>';return}const w=words[i],wrong=words.filter(x=>x.word!==w.word).sort(()=>Math.random()-.5).slice(0,2).map(x=>x.meaning);document.getElementById('word').textContent=w.word;document.getElementById('answers').innerHTML=[w.meaning,...wrong].sort(()=>Math.random()-.5).map(a=>`<button>${a}</button>`).join('')}async function send(answer,mode='choice'){const b=new FormData;b.append('word',words[i].word);b.append('answer',answer);b.append('mode',mode);const r=await fetch(url,{method:'POST',body:b,headers:{'X-Requested-With':'XMLHttpRequest'}}),j=await r.json();document.getElementById('status').textContent=j.feedback;if(j.correct)setTimeout(()=>{i++;draw()},800)}document.getElementById('answers').onclick=e=>{if(e.target.tagName==='BUTTON')send(e.target.textContent)};document.getElementById('speak').onclick=()=>{const R=window.SpeechRecognition||window.webkitSpeechRecognition;if(!R)return alert('Gunakan Chrome/Edge untuk latihan bicara.');const r=new R();r.lang='en-US';r.onresult=e=>send(e.results[0][0].transcript,'speaking');r.start()};draw()</script></body></html>
